"""Sensor-driven KinDER controller. Uses only the documented client API."""
import json, sys, numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
S=json.load(open('/app/output/spec.json'))
J=np.array(S['arm']['position_m']); A=np.array(S['arm']['axis']); E=np.array(S['arm']['end_effector']['position_m'])
def transform(q):
 T=np.eye(4)
 for p,a,t in zip(J,A,q):
  R=Rotation.from_rotvec(a*t).as_matrix(); M=np.eye(4); M[:3,:3]=R; M[:3,3]=p-R@p; T=T@M
 return T
def fk(q,b):
 T=transform(q); R=Rotation.from_euler('z',b[2]).as_matrix(); return R@(T[:3,:3]@E+T[:3,3])+np.r_[b[:2],0],R@T[:3,:3]
def camera(q,b):
 T=transform(q); R=Rotation.from_euler('z',b[2]).as_matrix(); P=S['cameras']['robot_wrist']['pose']; return R@(T[:3,:3]@P['position_m']+T[:3,3])+np.r_[b[:2],0],R@T[:3,:3]@np.array([P['right'],P['up'],P['forward']]).T
class Controller:
 def __init__(self): self.r=Robot(); self.o=self.r.observe(images=False)
 def snap(self):
  self.o=self.r.observe();
  for k,v in self.o['images'].items(): Image.fromarray(v).save('/app/output/'+k+'.png')
  np.savez('/app/output/obs.npz',**self.o.get('depth',{})); json.dump(self.o['proprio'],open('/app/output/proprio.json','w')); print(self.info())
 def info(self):
  p=self.o['proprio']; return {'step':self.o['step'],'blocked':self.o.get('blocked'),'done':self.o['done'],'reason':self.o['reason'],'proprio':p,'ee':fk(p['arm_pos'],p['base_pose'])[0].tolist()}
 def movej(self,q,b=None):
  p=self.o['proprio']; q0=np.array(p['arm_pos']); b0=np.array(p['base_pose']); b=b0 if b is None else np.array(b)
  n=int(np.ceil(max(np.max(np.abs(q-q0))/.08,np.linalg.norm(b[:2]-b0[:2])/.04,abs(b[2]-b0[2])/.08)))+1
  actions=np.tile(np.r_[(b-b0)/n,(q-q0)/n,0],(n,1)); self.o=self.r.step('delta',actions,images=False); print(self.info()); return not self.o.get('blocked')
 def ik(self,xyz,R=None):
  p=self.o['proprio']; q0=np.array(p['arm_pos']); b=p['base_pose']; R=fk(q0,b)[1] if R is None else R
  lo=np.array([-100,-2.41,-100,-2.66,-100,-2.23,-100]); hi=-lo
  def fun(q):
   x,r=fk(q,b); return np.r_[(x-xyz)*4,Rotation.from_matrix(R@r.T).as_rotvec(),.002*(q-q0)]
  res=least_squares(fun,q0,bounds=(lo,hi),max_nfev=500,ftol=1e-11,xtol=1e-11,gtol=1e-11)
  print('IK',res.cost,'target',xyz,'result',fk(res.x,b)[0]); return res.x
 def movep(self,xyz,R=None): return self.movej(self.ik(np.array(xyz),R))
 def grip(self,close): self.o=self.r.step('delta',[0]*10+[-1 if close else 1],images=False); print(self.info())
if __name__=='__main__':
 c=Controller()
 if len(sys.argv)>1: exec(sys.argv[1])
 else: c.snap()
